import{_ as a,o as r,c as t,a3 as i}from"./chunks/framework.D3oaa6bG.js";const h=JSON.parse('{"title":"Currencies","description":"","frontmatter":{},"headers":[],"relativePath":"guide/usage/currencies.md","filePath":"guide/usage/currencies.md","lastUpdated":null}'),c={name:"guide/usage/currencies.md"};function n(o,e,d,l,u,s){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="currencies" tabindex="-1">Currencies <a class="header-anchor" href="#currencies" aria-label="Permalink to &quot;Currencies&quot;">​</a></h1><p>Currencies can be managed via <code>Backend settings &gt; Mall: General &gt; Currencies</code>. They are used for all pricing information in the plugin.</p><h2 id="format" tabindex="-1">Format <a class="header-anchor" href="#format" aria-label="Permalink to &quot;Format&quot;">​</a></h2><p>A custom format for each currency can be defined in the <code>Format</code> code editor.</p><h2 id="rate" tabindex="-1">Rate <a class="header-anchor" href="#rate" aria-label="Permalink to &quot;Rate&quot;">​</a></h2><p>Every currency can be given a <code>Rate</code> that is relative to the default currency. If a price in a specific currency is not defined, it will be automatically calculated by multiplying the price from the default currency by the defined rate.</p><p>If the base currency is Euro, a rate of 1.15 could be defined for USD.</p><h2 id="twig-filter" tabindex="-1">Twig-Filter <a class="header-anchor" href="#twig-filter" aria-label="Permalink to &quot;Twig-Filter&quot;">​</a></h2><p>You can use the Twig filter <code> | money</code> to format any number in the currently active currency.</p><div><p><code>{{ 2000 | money }}</code> results in <code>$ 20.00</code>.</p></div>',10)])])}const p=a(c,[["render",n]]);export{h as __pageData,p as default};
